def draft_card(gw, ctx, case):
    ps = fetch_passages(ctx.owner_token, case)                  # only what the owner may read
    if len(ps) < 3:
        return None
    out = gw.json(model=SMALL, schema=CardOut, prompt=render(ps))
    ids = {p.id for p in ps}
    for name, f in out.fields():
        if not f.passage_ids or not set(f.passage_ids) <= ids:
            setattr(out, name, Field.empty())                  # uncited means blank
    return save_draft(ctx.owner, out)

cp_lib.code:
def publish(db, card, library, reviewer):
    assert library in LIBRARIES and reviewer != card.owner or card.owner_is_reviewer_ok
    row = db.insert("entries", id=new_id(), library=library, owner=card.owner, reviewer=reviewer, reviewed_at=today(), zone=card.zone, fields=card.fields, sources=card.sources)
    catalog.add(row)                                           # ix_cat gets type, owner, period
    return row

def rank(entry, base, interval=180):
    age = (today() - entry.reviewed_at).days
    return base * 0.5 ** max(0, (age - interval) / interval)

