def probe_draft(ctx, draft, budget=6):
    out = []
    for c in draft.claims:
        if budget == 0:
            out.append(ProbeResult(c.id, 'unchecked')); continue
        r = ctx.read_only_tool(c.source, c.test)   # contributor token
        budget -= 1
        out.append(classify(c, r))
    return out

