def check_dup(ctx, draft):
    near = ctx.library.nearest(draft, k=5, tags=draft.tags)
    if not near:
        return DupMark('new', [])
    return ctx.gw.json(model=SMALL, schema=DupMark, prompt=render(draft, near))

