def tier_for(cases, clean_cycles, contradicted):
    if contradicted:
        return 'prediction'
    if clean_cycles >= ANCHOR_CYCLES:
        return 'anchor'
    return 'core' if len({c.contributor for c in cases}) >= CORE_CASES else 'prediction'
